import {resolveCanvasShortcut} from './keyboard-shortcuts';

export interface CanvasPreparedAsset {kind: 'sprite' | 'backdrop'; costumes?: Awaited<ReturnType<typeof exportCostumeSet>>; backdrop?: Awaited<ReturnType<typeof exportCanvasTarget>>}

const props=defineProps<{initialInput:CanvasInput|null;bridge:ScratchGuiBridge|null;handoffMode?: 'direct-import' | 'return-prepared-asset'}>(); const emit=defineEmits<{close:[];prepared: [payload: {kind: 'sprite' | 'backdrop'; costumes?: Awaited<ReturnType<typeof exportCostumeSet>>; backdrop?: Awaited<ReturnType<typeof exportCanvasTarget>>}]}>();
const documentState=ref<CanvasDocument|null>(null); const bitmaps=new BitmapStore(); const history=new HistoryManager(); const canvas=ref<HTMLCanvasElement|null>(null); const viewport=ref<HTMLElement|null>(null); const fileInput=ref<HTMLInputElement|null>(null); const tool=ref<CanvasTool>('move'); const panelTab=ref<'layers'|'costumes'>('layers'); const status=ref('导入图片或从 Scratch 导入以开始'); const busy=ref(false); const scratchImportOpen=ref(false); const scratchExportOpen=ref(false); const scratchOptions=ref<ScratchImportOption[]>([]); const zoomLabel=computed(()=>Math.round((documentState.value?.viewport.zoom??1)*100)+'%'); const active=computed(()=>documentState.value?activeLayer(documentState.value):null); const costumeLayerIds=computed(()=>new Set(documentState.value?.costumeEntries.map(entry=>entry.layerId)??[]));
const previewCostumeId=ref<string|null>(null); const shortcutHelpOpen=ref(false); const inspectorOpen=ref(!window.matchMedia('(max-width: 700px)').matches); const chromaTolerance=ref(26); const chromaSoftness=ref(8); const chromaMode=ref<'connected'|'global'>('connected'); const spill=ref(35); const brushSize=ref(16); const paintColor=ref('#2f80ed'); const cropRect=ref<Rect|null>(null); const manualSelection=ref(false); let resizeObserver:ResizeObserver|null=null; let recoveryTimer:number|null=null; let skipRecoveryOnUnmount=false; let frame=0; let spacePressed=false;
let pointer:{id:number;startScreen:Point;startWorld:Point;lastWorld:Point;mode:'pan'|'select'|'crop-resize'|'crop-move'|'move'|'resize'|'draw';layerStart?:Point;layerId?:string;handle?:ControlHandle;transformStart?:Matrix2D;rectStart?:Rect}|null=null;

async function persistRecovery(){if(!documentState.value)return;try{await saveRecovery(documentState.value,bitmaps);}catch{}}
function scheduleRecovery(){if(!documentState.value)return;if(recoveryTimer!==null)window.clearTimeout(recoveryTimer);recoveryTimer=window.setTimeout(()=>{recoveryTimer=null;void persistRecovery();},300);}
function touch(message?:string){if(message)status.value=message; scheduleRecovery(); window.cancelAnimationFrame(frame); frame=window.requestAnimationFrame(render);}
function drawControlFrame(ctx:CanvasRenderingContext2D,points:ControlPoints,zoom:number,color='#2f80ed'){const size=8/zoom;ctx.save();ctx.strokeStyle=color;ctx.fillStyle='#fff';ctx.lineWidth=1.5/zoom;ctx.setLineDash([]);ctx.beginPath();ctx.moveTo(points.nw.x,points.nw.y);ctx.lineTo(points.ne.x,points.ne.y);ctx.lineTo(points.se.x,points.se.y);ctx.lineTo(points.sw.x,points.sw.y);ctx.closePath();ctx.stroke();for(const handle of CONTROL_HANDLES){const point=points[handle],wide=handle==='n'||handle==='s',tall=handle==='e'||handle==='w';ctx.beginPath();ctx.rect(point.x-(wide?size*.75:size/2),point.y-(tall?size*.75:size/2),wide?size*1.5:size,tall?size*1.5:size);ctx.fill();ctx.stroke();}ctx.restore();}
function drawCropOverlay(ctx:CanvasRenderingContext2D,board:Rect,crop:Rect){ctx.save();ctx.fillStyle='rgba(0,0,0,.48)';ctx.beginPath();ctx.rect(board.x,board.y,board.width,board.height);ctx.rect(crop.x,crop.y,crop.width,crop.height);ctx.fill('evenodd');ctx.restore();}
function render(){const target=canvas.value,host=viewport.value,doc=documentState.value;if(!target||!host)return;const rect=host.getBoundingClientRect(),dpr=window.devicePixelRatio||1;target.width=Math.max(1,Math.round(rect.width*dpr));target.height=Math.max(1,Math.round(rect.height*dpr));target.style.width=rect.width+'px';target.style.height=rect.height+'px';const ctx=target.getContext('2d');if(!ctx)return;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#34383f';ctx.fillRect(0,0,rect.width,rect.height);if(!doc)return;const view=doc.viewport;ctx.save();ctx.translate(view.x,view.y);ctx.scale(view.zoom,view.zoom);const board=doc.artboard;ctx.fillStyle='#f8f8f9';ctx.fillRect(board.x,board.y,board.width,board.height);const checker=12/view.zoom,columns=Math.ceil(board.width/checker),rows=Math.ceil(board.height/checker);ctx.save();ctx.beginPath();ctx.rect(board.x,board.y,board.width,board.height);ctx.clip();ctx.fillStyle='#e8e9eb';for(let row=0;row<rows;row++)for(let column=0;column<columns;column++){if((column+row)%2===0)continue;ctx.fillRect(board.x+column*checker,board.y+row*checker,checker,checker);}ctx.restore();ctx.strokeStyle='#aab0ba';ctx.lineWidth=1/view.zoom;ctx.strokeRect(board.x,board.y,board.width,board.height);const previewEntry=doc.costumeEntries.find(entry=>entry.id===previewCostumeId.value);const visibleLayers=previewEntry?doc.layers.filter(layer=>layer.id===previewEntry.layerId):doc.layers;for(const layer of visibleLayers){if(!previewEntry&&!layer.visible)continue;const source=imageDataCanvas(layerImageData(layer,bitmaps)),t=layer.transform;ctx.save();ctx.globalAlpha=layer.opacity;ctx.transform(t.a,t.b,t.c,t.d,t.e,t.f);ctx.imageSmoothingEnabled=doc.viewport.zoom<8;ctx.drawImage(source,layer.bounds.x,layer.bounds.y,layer.bounds.width,layer.bounds.height);ctx.restore();}if(previewEntry){const r=previewEntry.frameRect,p=previewEntry.pivot;ctx.save();ctx.strokeStyle='#ffcc33';ctx.lineWidth=1.5/view.zoom;ctx.strokeRect(r.x,r.y,r.width,r.height);ctx.beginPath();ctx.moveTo(p.x-8/view.zoom,p.y);ctx.lineTo(p.x+8/view.zoom,p.y);ctx.moveTo(p.x,p.y-8/view.zoom);ctx.lineTo(p.x,p.y+8/view.zoom);ctx.stroke();ctx.restore();}if(tool.value==='crop'&&cropRect.value){drawCropOverlay(ctx,board,cropRect.value);drawControlFrame(ctx,rectControlPoints(cropRect.value),view.zoom,active.value?.locked?'#8b929d':'#2f80ed');}else if(tool.value==='transform'&&active.value?.visible&&!previewEntry)drawControlFrame(ctx,layerControlPoints(active.value.bounds,active.value.transform),view.zoom,active.value.locked?'#8b929d':'#2f80ed');if(doc.selection){const r=doc.selection.rect;ctx.save();ctx.setLineDash([6/view.zoom,4/view.zoom]);ctx.lineWidth=1.5/view.zoom;ctx.strokeStyle='#fff';ctx.strokeRect(r.x,r.y,r.width,r.height);ctx.lineDashOffset=5/view.zoom;ctx.strokeStyle='#111';ctx.strokeRect(r.x,r.y,r.width,r.height);ctx.restore();}ctx.restore();}
const layerPreviewCache=new Map<string,{signature:string;url:string}>();
function layerPreviewUrl(layer:RasterLayer){try{const bitmap=bitmaps.get(layer.bitmapId),signature=bitmap.revision+':'+JSON.stringify(layer.chromaKey);const cached=layerPreviewCache.get(layer.id);if(cached?.signature===signature)return cached.url;const url=imageDataCanvas(layerImageData(layer,bitmaps)).toDataURL('image/png');layerPreviewCache.set(layer.id,{signature,url});return url;}catch{return '';}}
function screenPoint(event:PointerEvent|WheelEvent){const rect=canvas.value!.getBoundingClientRect();return{x:event.clientX-rect.left,y:event.clientY-rect.top};}
function worldPoint(event:PointerEvent|WheelEvent){const p=screenPoint(event),view=documentState.value!.viewport;return{x:(p.x-view.x)/view.zoom,y:(p.y-view.y)/view.zoom};}
function fitView(){const doc=documentState.value,host=viewport.value;if(!doc||!host)return;const rect=host.getBoundingClientRect(),padding=72;const zoom=clamp(Math.min((rect.width-padding)/doc.artboard.width,(rect.height-padding)/doc.artboard.height),.05,32);doc.viewport.zoom=zoom;doc.viewport.x=(rect.width-doc.artboard.width*zoom)/2-doc.artboard.x*zoom;doc.viewport.y=(rect.height-doc.artboard.height*zoom)/2-doc.artboard.y*zoom;touch('已适应内容');}
async function loadInput(input:CanvasInput){busy.value=true;try{documentState.value=await importCanvasImage(input,bitmaps);history.reset();await nextTick();fitView();status.value='原图已载入，可直接编辑';}catch(error){status.value=error instanceof Error?error.message:'图片导入失败';}finally{busy.value=false;}}
async function onFiles(files:FileList|null|undefined,source:'upload'|'drop'='upload'){const file=files?.[0];if(!file)return;await loadInput({kind:'blob',blob:file,fileName:file.name,source});}
function showScratchImport(){if(!props.bridge)return;try{scratchOptions.value=listScratchImportOptions(props.bridge);scratchImportOpen.value=true;}catch(error){status.value=error instanceof Error?error.message:String(error);}}
async function chooseScratchImport(option:ScratchImportOption){if(!props.bridge||busy.value)return;busy.value=true;const previous=bitmaps.snapshot();try{bitmaps.restore([]);documentState.value=await importScratchSelection(props.bridge,option,bitmaps);history.reset();scratchImportOpen.value=false;panelTab.value=option.kind==='sprite'?'costumes':'layers';await nextTick();fitView();status.value=option.kind==='sprite'?'已从 Scratch 导入角色“'+option.name+'”，共 '+documentState.value.layers.length+' 个造型图层':'已从 Scratch 导入背景“'+option.name+'”';touch();}catch(error){bitmaps.restore(previous);status.value=error instanceof Error?error.message:String(error);}finally{busy.value=false;}}
function mutate(label:string,fn:()=>void){const doc=documentState.value;if(!doc)return;history.begin(label,doc,bitmaps);try{fn();doc.updatedAt=Date.now();history.commit(doc,bitmaps);touch(label);}catch(error){history.cancel();status.value=error instanceof Error?error.message:String(error);}}
function undo(){const restored=history.undo(bitmaps);if(restored){documentState.value=restored;touch('已撤销：'+history.redoLabel);}}
function redo(){const restored=history.redo(bitmaps);if(restored){documentState.value=restored;touch('已重做：'+history.undoLabel);}}
function zoomAt(point:Point,factor:number){const doc=documentState.value;if(!doc)return;const old=doc.viewport.zoom,next=clamp(old*factor,.05,32);doc.viewport.x=point.x-(point.x-doc.viewport.x)*(next/old);doc.viewport.y=point.y-(point.y-doc.viewport.y)*(next/old);doc.viewport.zoom=next;touch();}
function onWheel(event:WheelEvent){event.preventDefault();zoomAt(screenPoint(event),Math.exp(-event.deltaY*.0015));}
function layerCoordinates(layer:RasterLayer,p:Point){const t=layer.transform,det=t.a*t.d-t.b*t.c;if(Math.abs(det)<1e-8)return{x:-1,y:-1};const localX=(t.d*(p.x-t.e)-t.c*(p.y-t.f))/det,localY=(-t.b*(p.x-t.e)+t.a*(p.y-t.f))/det,image=bitmaps.getImageData(layer.bitmapId);return{x:Math.floor((localX-layer.bounds.x)*image.width/layer.bounds.width),y:Math.floor((localY-layer.bounds.y)*image.height/layer.bounds.height)};}
function transformValue(field:'x'|'y'|'width'|'height'|'angle'){const layer=active.value;if(!layer)return 0;const t=layer.transform;if(field==='x')return t.a*layer.bounds.x+t.c*layer.bounds.y+t.e;if(field==='y')return t.b*layer.bounds.x+t.d*layer.bounds.y+t.f;if(field==='width')return layer.bounds.width*Math.hypot(t.a,t.b);if(field==='height')return layer.bounds.height*Math.hypot(t.c,t.d);return Math.atan2(t.b,t.a)*180/Math.PI;}
function updateArtboard(field:'x'|'y'|'width'|'height',value:number){if(!documentState.value||!Number.isFinite(value))return;mutate('调整合成画框',()=>{documentState.value!.artboard[field]=field==='width'||field==='height'?Math.max(1,value):value;});}
function setArtboardRatio(ratio:number){const doc=documentState.value;if(!doc)return;mutate('设置画框比例',()=>{const centerY=doc.artboard.y+doc.artboard.height/2;doc.artboard.height=Math.max(1,doc.artboard.width/ratio);doc.artboard.y=centerY-doc.artboard.height/2;});}
function updateTransform(field:'x'|'y'|'width'|'height'|'angle',value:number){const layer=active.value;if(!layer||!Number.isFinite(value))return;mutate('变换图层',()=>{const t=layer.transform,b=layer.bounds;if(field==='x'){t.e=value-t.a*b.x-t.c*b.y;return;}if(field==='y'){t.f=value-t.b*b.x-t.d*b.y;return;}let sx=Math.hypot(t.a,t.b),sy=Math.hypot(t.c,t.d),angle=Math.atan2(t.b,t.a);if(field==='width')sx=Math.max(.001,value/b.width);if(field==='height')sy=Math.max(.001,value/b.height);if(field==='angle')angle=value*Math.PI/180;const cos=Math.cos(angle),sin=Math.sin(angle);t.a=cos*sx;t.b=sin*sx;t.c=-sin*sy;t.d=cos*sy;});}
function sampleAt(layer:RasterLayer,p:Point,raw=false){const local=layerCoordinates(layer,p),image=raw?bitmaps.getImageData(layer.bitmapId):layerImageData(layer,bitmaps);if(local.x<0||local.y<0||local.x>=image.width||local.y>=image.height)return null;const offset=(local.y*image.width+local.x)*4;return{r:image.data[offset],g:image.data[offset+1],b:image.data[offset+2],a:image.data[offset+3]};}
function hex(color:{r:number;g:number;b:number}){return'#'+[color.r,color.g,color.b].map(value=>value.toString(16).padStart(2,'0')).join('');}
function pointInRect(point:Point,rect:Rect){return point.x>=rect.x&&point.x<=rect.x+rect.width&&point.y>=rect.y&&point.y<=rect.y+rect.height;}
function layerBounds(){const layer=active.value;return layer?transformedRectBounds(layer.bounds,layer.transform):null;}
function beginCrop(){cropRect.value=layerBounds();if(!cropRect.value)status.value='请先选择图像图层';else touch('拖动八向控制柄调整裁剪范围，按回车确认');}
function setTool(next:CanvasTool){if(next!==tool.value&&next!=='select'&&!manualSelection.value)clearSelection(false);tool.value=next;if(next==='crop')beginCrop();else cropRect.value=null;touch();}
function updateCropRect(field:keyof Rect,value:number){if(!cropRect.value||!Number.isFinite(value))return;cropRect.value={...cropRect.value,[field]:field==='width'||field==='height'?Math.max(1,value):value};touch();}
function confirmCrop(){if(!documentState.value||!cropRect.value)return;let confirmed=false;mutate('确认裁剪',()=>{cropRect.value=cropActiveLayer(documentState.value!,bitmaps,cropRect.value!);confirmed=true;});if(confirmed)setTool('move');}
function handleCursor(handle:ControlHandle){return({n:'ns-resize',s:'ns-resize',e:'ew-resize',w:'ew-resize',nw:'nwse-resize',se:'nwse-resize',ne:'nesw-resize',sw:'nesw-resize'} as Record<ControlHandle,string>)[handle];}
function updatePointerCursor(world:Point){const doc=documentState.value,target=canvas.value;if(!doc||!target)return;const tolerance=10/doc.viewport.zoom;if(tool.value==='crop'){const crop=cropRect.value;if(!crop){target.style.cursor='default';return;}const handle=hitControl(rectControlPoints(crop),world,tolerance);target.style.cursor=handle?handleCursor(handle):pointInRect(world,crop)?'move':'default';return;}if(tool.value==='transform'&&active.value?.visible){const handle=hitControl(layerControlPoints(active.value.bounds,active.value.transform),world,tolerance);target.style.cursor=handle?handleCursor(handle):'move';return;}if(tool.value==='move'){target.style.cursor='move';return;}target.style.cursor='';}
function drawDot(layer:RasterLayer,p:Point){const local=layerCoordinates(layer,p),image=bitmaps.getImageData(layer.bitmapId),radius=tool.value==='pencil'?0:Math.max(.5,brushSize.value/2),rgb=paintColor.value.match(/[a-fd]{2}/gi)?.map(v=>parseInt(v,16))??[47,128,237];for(let y=Math.floor(local.y-radius);y<=Math.ceil(local.y+radius);y++)for(let x=Math.floor(local.x-radius);x<=Math.ceil(local.x+radius);x++){if(x<0||y<0||x>=image.width||y>=image.height||Math.hypot(x-local.x,y-local.y)>radius+.35)continue;const i=(y*image.width+x)*4;if(tool.value==='eraser')image.data[i+3]=0;else{image.data[i]=rgb[0];image.data[i+1]=rgb[1];image.data[i+2]=rgb[2];image.data[i+3]=255;}}bitmaps.update(layer.bitmapId,image);layer.updatedAt=Date.now();touch();}
function fillAt(layer:RasterLayer,p:Point){const local=layerCoordinates(layer,p),image=bitmaps.getImageData(layer.bitmapId);if(local.x<0||local.y<0||local.x>=image.width||local.y>=image.height)return;const rgb=paintColor.value.match(/[a-fd]{2}/gi)?.map(v=>parseInt(v,16))??[47,128,237],start=(local.y*image.width+local.x)*4,target=[...image.data.slice(start,start+4)],seen=new Uint8Array(image.width*image.height),queue=[[local.x,local.y]];for(let c=0;c<queue.length;c++){const [x,y]=queue[c],index=y*image.width+x;if(seen[index])continue;seen[index]=1;const o=index*4;if(Math.max(...target.map((v,i)=>Math.abs(v-image.data[o+i])))>18)continue;image.data[o]=rgb[0];image.data[o+1]=rgb[1];image.data[o+2]=rgb[2];image.data[o+3]=255;[[x-1,y],[x+1,y],[x,y-1],[x,y+1]].forEach(([nx,ny])=>{if(nx>=0&&ny>=0&&nx<image.width&&ny<image.height)queue.push([nx,ny]);});}bitmaps.update(layer.bitmapId,image);}
function onPointerDown(event:PointerEvent){const doc=documentState.value;if(!doc)return;(event.currentTarget as HTMLElement).setPointerCapture(event.pointerId);const screen=screenPoint(event),world=worldPoint(event);if(spacePressed||tool.value==='hand'){pointer={id:event.pointerId,startScreen:screen,startWorld:world,lastWorld:world,mode:'pan'};return;}if(tool.value==='zoom'){zoomAt(screen,event.shiftKey?.8:1.25);return;}if(tool.value==='select'){pointer={id:event.pointerId,startScreen:screen,startWorld:world,lastWorld:world,mode:'select'};doc.selection={rect:{x:world.x,y:world.y,width:0,height:0},mode:'replace'};touch();return;}if(tool.value==='transform'){const layer=active.value,bounds=layerBounds();if(!layer||!bounds){status.value='请先选择图像图层';return;}if(layer.locked){status.value='请先解锁当前图层';return;}const handle=hitControl(layerControlPoints(layer.bounds,layer.transform),world,10/doc.viewport.zoom);if(handle){history.begin('缩放图层',doc,bitmaps);pointer={id:event.pointerId,startScreen:screen,startWorld:world,lastWorld:world,mode:'resize',layerId:layer.id,handle,transformStart:{...layer.transform}};}else if(pointInRect(world,bounds)){history.begin('移动图层',doc,bitmaps);pointer={id:event.pointerId,startScreen:screen,startWorld:world,lastWorld:world,mode:'move',layerId:layer.id,layerStart:{x:layer.transform.e,y:layer.transform.f}};}else status.value='请拖动图层边缘、四角或框内区域';return;}if(tool.value==='crop'){const crop=cropRect.value;if(!active.value||!crop){status.value='请先选择图像图层';return;}const handle=hitControl(rectControlPoints(crop),world,10/doc.viewport.zoom);if(handle)pointer={id:event.pointerId,startScreen:screen,startWorld:world,lastWorld:world,mode:'crop-resize',handle,rectStart:{...crop}};else if(pointInRect(world,crop))pointer={id:event.pointerId,startScreen:screen,startWorld:world,lastWorld:world,mode:'crop-move',rectStart:{...crop}};else status.value='请拖动裁剪框边缘、四角或框内区域';return;}const pixelTool=['brush','pencil','eraser','fill'].includes(tool.value);const hit=pixelTool?null:hitTestLayer(doc,bitmaps,world,tool.value==='chroma');if(hit&&hit.id!==doc.activeLayerIds[0]){doc.activeLayerIds=[hit.id];panelTab.value='layers';touch('已选择图层：'+hit.name);}const layer=pixelTool?active.value:(hit??active.value);if(!layer)return;if(tool.value==='chroma'||tool.value==='eyedropper'){const local=layerCoordinates(layer,world),color=sampleAt(layer,world,tool.value==='chroma');if(!color)return;paintColor.value=hex(color);if(tool.value==='chroma'){mutate('保存色度抠图',()=>{const source=layer.chromaKey?applyChromaKey(bitmaps.getImageData(layer.bitmapId),layer.chromaKey):bitmaps.getImageData(layer.bitmapId);const effect:ChromaKeyEffect={keyColor:{r:color.r,g:color.g,b:color.b},tolerance:chromaTolerance.value,softness:chromaSoftness.value,mode:chromaMode.value,seedMode:'points',connectivity:8,spillSuppression:spill.value,inverted:false,seedPoints:[local],enabled:true};bitmaps.update(layer.bitmapId,applyChromaKey(source,effect));layer.chromaKey=null;layer.updatedAt=Date.now();});}else status.value='已取色 '+paintColor.value;return;}if(layer.locked){status.value='请先解锁当前图层';return;}if(tool.value==='move'){history.begin('移动图层',doc,bitmaps);pointer={id:event.pointerId,startScreen:screen,startWorld:world,lastWorld:world,mode:'move',layerId:layer.id,layerStart:{x:layer.transform.e,y:layer.transform.f}};return;}if(['brush','pencil','eraser'].includes(tool.value)){if(layer.chromaKey){status.value='像素编辑前请先关闭或栅格化色度效果';return;}history.begin(tool.value==='eraser'?'橡皮擦':'绘制',doc,bitmaps);pointer={id:event.pointerId,startScreen:screen,startWorld:world,lastWorld:world,mode:'draw',layerId:layer.id};drawDot(layer,world);return;}if(tool.value==='fill'){if(layer.chromaKey){status.value='填充前请先关闭色度效果';return;}mutate('油漆桶填充',()=>fillAt(layer,world));}}
function onPointerMove(event:PointerEvent){const doc=documentState.value;if(!doc)return;const screen=screenPoint(event),world=worldPoint(event);if(!pointer||pointer.id!==event.pointerId){updatePointerCursor(world);return;}if(pointer.mode==='pan'){doc.viewport.x+=screen.x-pointer.startScreen.x;doc.viewport.y+=screen.y-pointer.startScreen.y;pointer.startScreen=screen;touch();return;}if(pointer.mode==='select'){doc.selection={rect:normalizeRect(pointer.startWorld,world),mode:'replace'};touch();return;}if(pointer.mode==='crop-resize'&&pointer.handle&&pointer.rectStart){cropRect.value=resizeRectFromHandle(pointer.rectStart,pointer.handle,world);touch();return;}if(pointer.mode==='crop-move'&&pointer.rectStart){cropRect.value={...pointer.rectStart,x:pointer.rectStart.x+world.x-pointer.startWorld.x,y:pointer.rectStart.y+world.y-pointer.startWorld.y};touch();return;}const layer=pointer.layerId?doc.layers.find(item=>item.id===pointer!.layerId)??null:active.value;if(!layer)return;if(pointer.mode==='resize'&&pointer.handle&&pointer.transformStart){layer.transform=resizeLayerFromHandle(pointer.transformStart,layer.bounds,pointer.handle,world,event.shiftKey);touch();return;}if(pointer.mode==='move'&&pointer.layerStart){layer.transform.e=pointer.layerStart.x+world.x-pointer.startWorld.x;layer.transform.f=pointer.layerStart.y+world.y-pointer.startWorld.y;touch();return;}if(pointer.mode==='draw'){const dx=world.x-pointer.lastWorld.x,dy=world.y-pointer.lastWorld.y,steps=Math.max(1,Math.ceil(Math.hypot(dx,dy)/(Math.max(1,brushSize.value)/4)));for(let i=1;i<=steps;i++)drawDot(layer,{x:pointer.lastWorld.x+dx*i/steps,y:pointer.lastWorld.y+dy*i/steps});pointer.lastWorld=world;}}
function onPointerUp(event:PointerEvent){const doc=documentState.value;if(!doc||!pointer||pointer.id!==event.pointerId)return;const mode=pointer.mode;if(['move','resize','draw'].includes(mode))history.commit(doc,bitmaps);pointer=null;updatePointerCursor(worldPoint(event));touch(mode==='resize'?'已缩放图层':mode.startsWith('crop')?'已调整裁剪范围，按回车确认':undefined);}
function clearSelection(showStatus=true){if(!documentState.value?.selection)return;documentState.value.selection=null;touch(showStatus?'已取消选区':undefined);}
function createLayerFromSelection(cut=false){mutate(cut?'剪切选区为新图层':'复制选区为新图层',()=>copySelectionToLayer(documentState.value!,bitmaps,cut));panelTab.value='costumes';inspectorOpen.value=true;}
function toggleCostume(layerId:string){mutate('更新造型队列',()=>{const doc=documentState.value!,existing=doc.costumeEntries.find(entry=>entry.layerId===layerId);if(existing)doc.costumeEntries=doc.costumeEntries.filter(entry=>entry.id!==existing.id).map((entry,order)=>({...entry,order}));else{const layer=doc.layers.find(item=>item.id===layerId)!;const frame=transformedRectBounds(layer.bounds,layer.transform);doc.costumeEntries.push({id:createId(),layerId,name:layer.name,order:doc.costumeEntries.length,frameRect:frame,pivot:{x:frame.x+frame.width/2,y:frame.y+frame.height/2},alignment:'center',exportScale:2,enabled:true});}});}
function addBlank(){mutate('新建空白图层',()=>{const doc=documentState.value!,image=new ImageData(Math.max(1,Math.round(doc.artboard.width)),Math.max(1,Math.round(doc.artboard.height))),now=Date.now(),layer:RasterLayer={id:createId(),name:'图层 '+(doc.layers.length+1),bitmapId:bitmaps.put(image),bounds:{...doc.artboard},transform:{...IDENTITY_MATRIX},visible:true,locked:false,opacity:1,blendMode:'normal',chromaKey:null,createdAt:now,updatedAt:now};doc.layers.push(layer);doc.activeLayerIds=[layer.id];});}
function updateChroma(){const layer=active.value;if(!layer?.chromaKey)return;mutate('调整色度抠图',()=>Object.assign(layer.chromaKey!,{tolerance:chromaTolerance.value,softness:chromaSoftness.value,mode:chromaMode.value,spillSuppression:spill.value}));}
function moveCostume(id:string,direction:-1|1){mutate('调整造型顺序',()=>{const list=documentState.value!.costumeEntries,index=list.findIndex(entry=>entry.id===id),target=index+direction;if(target<0||target>=list.length)return;[list[index],list[target]]=[list[target],list[index]];list.forEach((entry,order)=>entry.order=order);});}
async function exportComposite(){if(!documentState.value)return;busy.value=true;try{await downloadComposite(documentState.value,bitmaps);status.value='合成 PNG 已下载';}catch(e){status.value=e instanceof Error?e.message:String(e);}finally{busy.value=false;}}
async function exportZip(){if(!documentState.value)return;busy.value=true;try{await downloadCostumeZip(documentState.value,bitmaps);status.value='造型 ZIP 已下载';}catch(e){status.value=e instanceof Error?e.message:String(e);}finally{busy.value=false;}}
async function importScratch(target:'sprite'|'backdrop'){if(!documentState.value||busy.value)return;busy.value=true;try{if(target==='backdrop'){const backdrop=await exportCanvasTarget(documentState.value,bitmaps,'backdrop');if(props.handoffMode==='return-prepared-asset'){emit('prepared',{kind:'backdrop',backdrop});status.value='背景已准备，等待项目提交';}else{if(!props.bridge) return;await importBackdropCostume(props.bridge,backdrop);status.value='已将完整画板导入为 Scratch 背景';}}else{const costumes=documentState.value.costumeEntries.length?await exportCostumeSet(documentState.value,bitmaps):[await exportCanvasTarget(documentState.value,bitmaps,'sprite')];if(props.handoffMode==='return-prepared-asset'){emit('prepared',{kind:'sprite',costumes});status.value='角色造型已准备，等待项目提交';}else{if(!props.bridge) return;const result=await importCostumeSet(props.bridge,{name:documentState.value.name,costumes,initialSize:fitSpriteInitialSize(costumes)});status.value='已创建角色，包含 '+costumes.length+' 个造型（'+result.targetId+'）';}}if(props.handoffMode!=='return-prepared-asset'){await clearRecovery();skipRecoveryOnUnmount=true;scratchExportOpen.value=false;emit('close');}}catch(e){status.value=e instanceof Error?e.message:String(e);}finally{busy.value=false;}}
function onKey(event:KeyboardEvent){const editing=event.composedPath().some(target=>target instanceof HTMLElement&&(['INPUT','TEXTAREA','SELECT'].includes(target.tagName)||target.isContentEditable));const consume=()=>{event.preventDefault();event.stopImmediatePropagation();};if(event.code==='Space'){if(event.type==='keyup'){if(spacePressed){spacePressed=false;consume();}return;}if(editing)return;spacePressed=true;consume();return;}if(event.type!=='keydown'||editing)return;if(event.code==='Enter'&&tool.value==='crop'){consume();if(!event.repeat)confirmCrop();return;}const shortcut=resolveCanvasShortcut(event);if(!shortcut)return;consume();if(shortcut.kind==='undo'){undo();return;}if(shortcut.kind==='redo'){redo();return;}if(shortcut.kind==='copy-selection'){if(!event.repeat)createLayerFromSelection(shortcut.cut);return;}if(shortcut.kind==='fit-view'){fitView();return;}if(shortcut.kind==='actual-size'){if(documentState.value){documentState.value.viewport.zoom=1;touch();}return;}if(shortcut.kind==='tool'){setTool(shortcut.tool);return;}if(tool.value==='crop'){setTool('move');return;}if(shortcutHelpOpen.value)shortcutHelpOpen.value=false;else if(documentState.value?.selection)clearSelection();else emit('close');}
async function initializeCanvas(){if(props.initialInput){await loadInput(props.initialInput);return;}try{const recovery=await loadRecovery();if(recovery){bitmaps.restore(recovery.bitmaps);documentState.value=recovery.document;history.reset();await nextTick();fitView();status.value='已恢复上次画布';}}catch(error){status.value=error instanceof Error?error.message:'画布恢复失败';}}
onMounted(async()=>{resizeObserver=new ResizeObserver(()=>documentState.value?fitView():touch());if(viewport.value)resizeObserver.observe(viewport.value);window.addEventListener('keydown',onKey,true);window.addEventListener('keyup',onKey,true);window.addEventListener('paste',onPaste);await initializeCanvas();viewport.value?.focus();touch();});
function onPaste(event:ClipboardEvent){const file=[...(event.clipboardData?.files??[])].find(item=>item.type.startsWith('image/'));if(file)loadInput({kind:'blob',blob:file,fileName:'剪贴板图片.png',source:'clipboard'});}
onBeforeUnmount(()=>{if(recoveryTimer!==null)window.clearTimeout(recoveryTimer);if(!skipRecoveryOnUnmount)void persistRecovery();resizeObserver?.disconnect();window.removeEventListener('keydown',onKey,true);window.removeEventListener('keyup',onKey,true);window.removeEventListener('paste',onPaste);window.cancelAnimationFrame(frame);});
</script>

<template><section class="canvas-workspace" role="dialog" aria-modal="true" aria-label="无边画布编辑器"><header class="canvas-commandbar"><button class="canvas-commandbar__back" type="button" @click="emit('close')"><ArrowLeft :size="18"/>返回 Scratch</button><input v-if="documentState" v-model="documentState.name" class="canvas-document-name" aria-label="文档名称" @change="touch('文档已重命名')"/><span v-else class="canvas-document-name canvas-document-name--empty">无边画布</span><div class="canvas-commandbar__history"><button type="button" :disabled="!history.canUndo" :title="history.undoLabel?'撤销：'+history.undoLabel:'撤销'" aria-label="撤销" @click="undo"><Undo2 :size="17"/></button><button type="button" :disabled="!history.canRedo" :title="history.redoLabel?'重做：'+history.redoLabel:'重做'" aria-label="重做" @click="redo"><Redo2 :size="17"/></button></div><div class="canvas-commandbar__actions"><input ref="fileInput" class="visually-hidden" type="file" accept="image/png,image/jpeg,image/webp" @change="onFiles(($event.target as HTMLInputElement).files)"/><button type="button" @click="fileInput?.click()"><ImagePlus :size="17"/>导入图片</button><button type="button" :disabled="!props.bridge?.isReady||busy" @click="showScratchImport"><FolderInput :size="17"/>从 Scratch 导入</button><button type="button" :disabled="!documentState||busy" @click="exportComposite"><Download :size="17"/>PNG</button><button type="button" :disabled="!documentState?.costumeEntries.length||busy" @click="exportZip"><FileArchive :size="17"/>造型 ZIP</button><button class="inspector-toggle" type="button" :title="inspectorOpen?'收起属性面板':'展开属性面板'" :aria-label="inspectorOpen?'收起属性面板':'展开属性面板'" @click="inspectorOpen=!inspectorOpen"><SlidersHorizontal :size="17"/></button><button class="is-primary" type="button" :disabled="!documentState?.layers.length||!props.bridge||busy" @click="scratchExportOpen=true"><LoaderCircle v-if="busy" class="spin" :size="17"/><Upload v-else :size="17"/>导入 Scratch</button></div></header><div class="canvas-main"><CanvasToolbar :model-value="tool" :help-open="shortcutHelpOpen" @update:model-value="setTool" @fit="fitView" @help="shortcutHelpOpen=!shortcutHelpOpen"/><section v-if="shortcutHelpOpen" class="canvas-shortcuts" role="dialog" aria-label="画布快捷键帮助"><header><strong>快捷键</strong><button type="button" title="关闭快捷键帮助" aria-label="关闭快捷键帮助" @click="shortcutHelpOpen=false"><X :size="16"/></button></header><div><span>移动</span><kbd>V</kbd><span>变换</span><kbd>T</kbd><span>矩形选区</span><kbd>M</kbd><span>裁剪</span><kbd>C</kbd><span>色度抠图</span><kbd>K</kbd><span>画笔</span><kbd>B</kbd><span>铅笔</span><kbd>N</kbd><span>橡皮擦</span><kbd>E</kbd><span>吸管</span><kbd>I</kbd><span>抓手</span><kbd>H</kbd><span>临时抓手</span><kbd>Space</kbd></div><div class="canvas-shortcuts__commands"><span>复制选区为新图层</span><kbd>Alt J</kbd><span>剪切选区为新图层</span><kbd>Alt Shift J</kbd><span>适应内容</span><kbd>Ctrl 0</kbd><span>100% 显示</span><kbd>Ctrl 1</kbd><span>撤销</span><kbd>Ctrl Z</kbd><span>重做</span><kbd>Ctrl Shift Z</kbd></div></section><main ref="viewport" class="canvas-viewport" tabindex="0" :data-tool="tool" @wheel="onWheel" @pointerdown="onPointerDown" @pointermove="onPointerMove" @pointerup="onPointerUp" @pointercancel="onPointerUp" @dragover.prevent @drop.prevent="onFiles($event.dataTransfer?.files,'drop')"><canvas ref="canvas"/><div v-if="!documentState" class="canvas-empty"><ImagePlus :size="34"/><strong>导入一张角色素材</strong><span>支持 PNG、JPEG、WebP，也可以拖放或粘贴图片</span><button type="button" @click="fileInput?.click()"><ImagePlus :size="16"/>选择图片</button></div></main><aside class="canvas-inspector" :class="{'is-mobile-open':inspectorOpen}"><section class="tool-options"><h2>工具属性</h2><template v-if="tool==='chroma'"><label>目标颜色<input v-model="paintColor" type="color"/></label><label>容差 <span>{{chromaTolerance}}</span><input v-model.number="chromaTolerance" type="range" min="0" max="100" @change="updateChroma"/></label><label>柔化 <span>{{chromaSoftness}}</span><input v-model.number="chromaSoftness" type="range" min="0" max="40" @change="updateChroma"/></label><label>作用模式<select v-model="chromaMode" @change="updateChroma"><option value="connected">相邻背景</option><option value="global">全图同色</option></select></label><label>去色边 <span>{{spill}}</span><input v-model.number="spill" type="range" min="0" max="100" @change="updateChroma"/></label><p>在背景区域点击取色并应用效果。</p></template><template v-else-if="['brush','eraser'].includes(tool)"><label>笔刷大小 <span>{{brushSize}} px</span><input v-model.number="brushSize" type="range" min="1" max="128"/></label><label v-if="tool==='brush'">颜色<input v-model="paintColor" type="color"/></label></template><template v-else-if="tool==='pencil'||tool==='fill'||tool==='eyedropper'"><label>颜色<input v-model="paintColor" type="color"/></label></template><template v-else-if="tool==='select'"><label class="manual-selection-option"><input v-model="manualSelection" type="checkbox"/>手动建立选区</label><p>开启后切换工具时保留当前选区。</p><div class="selection-actions"><button type="button" :disabled="!documentState?.selection" @click.stop.prevent="createLayerFromSelection(false)">复制为新图层</button><button type="button" :disabled="!documentState?.selection" @click.stop.prevent="createLayerFromSelection(true)">剪切为新图层</button><button type="button" :disabled="!documentState?.selection" @click.stop.prevent="clearSelection()">取消选区</button></div></template><template v-else-if="tool==='crop'"><div v-if="cropRect" class="crop-options"><div class="transform-grid"><label>X<input type="number" step="1" :value="cropRect.x" @change="updateCropRect('x',($event.target as HTMLInputElement).valueAsNumber)"/></label><label>Y<input type="number" step="1" :value="cropRect.y" @change="updateCropRect('y',($event.target as HTMLInputElement).valueAsNumber)"/></label><label>宽<input type="number" min="1" step="1" :value="cropRect.width" @change="updateCropRect('width',($event.target as HTMLInputElement).valueAsNumber)"/></label><label>高<input type="number" min="1" step="1" :value="cropRect.height" @change="updateCropRect('height',($event.target as HTMLInputElement).valueAsNumber)"/></label><button type="button" :disabled="active?.locked" @click="confirmCrop">确认裁剪</button></div><p>调整裁剪框后按回车确认，图层位置保持不变。</p></div><p v-else>请先选择图层</p></template><template v-else-if="tool==='transform'"><div v-if="active" class="transform-grid"><label>X<input type="number" step="0.5" :value="transformValue('x')" @change="updateTransform('x',($event.target as HTMLInputElement).valueAsNumber)"/></label><label>Y<input type="number" step="0.5" :value="transformValue('y')" @change="updateTransform('y',($event.target as HTMLInputElement).valueAsNumber)"/></label><label>宽<input type="number" min="0.1" step="0.5" :value="transformValue('width')" @change="updateTransform('width',($event.target as HTMLInputElement).valueAsNumber)"/></label><label>高<input type="number" min="0.1" step="0.5" :value="transformValue('height')" @change="updateTransform('height',($event.target as HTMLInputElement).valueAsNumber)"/></label><label>角度<input type="number" step="1" :value="transformValue('angle')" @change="updateTransform('angle',($event.target as HTMLInputElement).valueAsNumber)"/></label><button type="button" :disabled="active.locked" @click="mutate('应用图层变换',()=>applyLayerTransform(documentState!,bitmaps))">应用变换</button></div><p v-else>请先选择图层</p></template><p v-else>在画布中操作，视图导航不进入撤销历史。</p></section><div class="inspector-tabs" role="tablist"><button :class="{'is-active':panelTab==='layers'}" role="tab" :aria-selected="panelTab==='layers'" @click="panelTab='layers'">图层 <span>{{documentState?.layers.length??0}}</span></button><button :class="{'is-active':panelTab==='costumes'}" role="tab" :aria-selected="panelTab==='costumes'" @click="panelTab='costumes'">造型 <span>{{documentState?.costumeEntries.length??0}}</span></button></div><LayersPanel v-if="panelTab==='layers'" :layers="documentState?.layers??[]" :active-id="documentState?.activeLayerIds[0]" :costume-layer-ids="costumeLayerIds" :preview-url="layerPreviewUrl" @select="id=>{if(documentState){documentState.activeLayerIds=[id];if(tool==='crop')beginCrop();else touch()}}" @toggle-visible="id=>mutate('切换图层显隐',()=>{const l=documentState!.layers.find(x=>x.id===id);if(l)l.visible=!l.visible})" @toggle-lock="id=>mutate('切换图层锁定',()=>{const l=documentState!.layers.find(x=>x.id===id);if(l)l.locked=!l.locked})" @rename="(id,name)=>mutate('重命名图层',()=>{const l=documentState!.layers.find(x=>x.id===id);if(l){l.name=name;const e=documentState!.costumeEntries.find(x=>x.layerId===id&&!x.manuallyNamed);if(e)e.name=name}})" @duplicate="mutate('复制图层',()=>duplicateLayer(documentState!,bitmaps))" @remove="mutate('删除图层',()=>deleteActiveLayer(documentState!,bitmaps))" @blank="addBlank" @toggle-costume="toggleCostume" @move="(id,direction)=>mutate('调整图层顺序',()=>reorderLayer(documentState!,id,direction))" @opacity="(id,value)=>mutate('调整图层透明度',()=>{const l=documentState!.layers.find(item=>item.id===id);if(l)l.opacity=value})"/><CostumesPanel v-else :entries="documentState?.costumeEntries??[]" :preview-id="previewCostumeId" @rename="(id,name)=>mutate('重命名造型',()=>{const e=documentState!.costumeEntries.find(x=>x.id===id);if(e){e.name=name;e.manuallyNamed=true}})" @remove="id=>mutate('移出造型队列',()=>{documentState!.costumeEntries=documentState!.costumeEntries.filter(x=>x.id!==id).map((x,order)=>({...x,order}))})" @move="moveCostume" @align="mode=>mutate('统一造型画框',()=>unifyCostumeFrames(documentState!,mode))" @pivot="(id,x,y)=>mutate('调整旋转中心',()=>{const e=documentState!.costumeEntries.find(item=>item.id===id);if(e){e.pivot={x,y};e.alignment='custom'}})" @scale="(id,value)=>mutate('调整输出比例',()=>{const e=documentState!.costumeEntries.find(item=>item.id===id);if(e&&Number.isFinite(value)&&value>0)e.exportScale=value})" @preview="id=>{previewCostumeId=previewCostumeId===id?null:id;touch(previewCostumeId?'正在预览造型':'已退出造型预览')}"/></aside></div><footer class="canvas-status"><span>{{status}}</span><span v-if="documentState?.selection">选区 {{Math.round(documentState.selection.rect.width)}} × {{Math.round(documentState.selection.rect.height)}}</span><span v-if="active">当前图层 {{Math.round(active.bounds.width)}} × {{Math.round(active.bounds.height)}}{{active.locked?' · 已锁定':''}}</span><span>{{zoomLabel}}</span></footer><ScratchImportDialog v-if="scratchImportOpen" :options="scratchOptions" :busy="busy" @close="scratchImportOpen=false" @select="chooseScratchImport"/><ScratchExportDialog v-if="scratchExportOpen" :busy="busy" @close="scratchExportOpen=false" @select="importScratch"/></section></template>
